def esc(s):return html.escape(str(s))
def table(head,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def flow(items):return '<div class="flow">'+'<span class="arrow">→</span>'.join('<div class="node">'+x+'</div>' for x in items)+'</div>'
def cards(items):return '<div class="grid">'+''.join('<div class="panel"><h3>'+a+'</h3><p>'+b+'</p></div>' for a,b in items)+'</div>'
def note(s,b=False):return '<div class="note '+('boundary' if b else '')+'">'+s+'</div>'
def section(title,body):return '<section><h2>'+title+'</h2>'+body+'</section>'
def page(file,title,body,script=''):
    txt='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><link rel="stylesheet" href="style.css"></head><body><header><strong>匠造智服 / SHOWCASE</strong>'+''.join('<a class="'+('active' if f==file else '')+'" href="'+f+'">'+n+'</a>' for f,n in nav)+'</header><main><div class="meta">生成时间：'+stamp+'　｜　数据截至时间：2026-10-26　｜　报告对象：三一匠造 3.5.0 参赛作品</div>'+body+'</main><footer>报告来源方:SDMC-IT</footer>'+('<script>'+script+'</script>' if script else '')+'</body></html>'
    (OUT/file).write_text(txt,encoding='utf-8')

matrix=[['售前需求协同','设备目录、分类检索、教学 3D、项目需求、保密清单、审核补充、本机客服','需求记录与沟通历史','有需求入口；无独立线索池、商机评级与销售预测'],['售中交付协同','购买／租赁申请、报价确认、备货、发运、客户收货','订单状态、报价、物流字段、材料和历史','备货是人工登记状态，不会扣减真实库存；物流非自动轨迹'],['售后服务闭环','报修、派单、工程师处理、独立材料审核、客户验收、退回处理','关联订单的维修工单及全过程材料','无资产台账、保修规则引擎、备件结算和 SLA 考核'],['贯穿全程的跟进','关联需求／订单／维修单；负责人、行动、截止时间、结果与调整记录','待办、逾期、本人任务、完成记录','跟进完成不自动改变主单据状态'],['平台管理与支撑','人员角色、产品维护、附件、审计、本机持久化','目录、权限检查与操作轨迹','非正式商用权限体系；未接入企业系统']]
ltc=[['ML 管理线索','部分支撑','目录触达、工程需求提交、沟通及后续行动','没有独立线索对象、来源归因、线索分配与转化率'],['MO 管理机会点','部分支撑','需求澄清、设备方案沟通、订单报价录入','没有商机阶段、投标、报价版本、谈判评审和合同签署'],['MCE 管理合同执行中的交付','订单交付子链路已实现','申请→报价确认→备货→发运→客户收货','无合同台账及合同／PO变更；不等于实现完整 MCE'],['开票与回款','未实现','目前不收取真实款项','无发票、应收、付款计划、回款核销、财务对账'],['交付后的售后延伸','服务子链路已实现','报修→工程师处理→独立审核→客户验收','售后与 LTC 衔接，但不能代替回款，也不代表全部服务运营']]
lanes='''<div class="lanes"><div class="lane"><b>阶段</b><div>需求与沟通</div><div>订单与报价</div><div>交付与签收</div><div>售后与验收</div></div><div class="lane"><b>客户端</b><div>浏览设备／提项目<br>咨询、补充需求</div><div>另行提交租购申请<br>查询报价与状态</div><div>查看发运信息<br>上传材料、确认收货</div><div>提交维保报修<br>验收或退回处理</div></div><div class="lane"><b>管理工作端</b><div>审核需求、沟通<br>建立跟进计划</div><div>受理订单<br>录入报价及材料</div><div>登记备货、发运<br>核对交付记录</div><div>派单、独立审核<br>工程师负责实际处理</div></div><div class="lane"><b>数据关联</b><div class="gap">项目→订单尚无自动转化</div><div>订单编号与历史</div><div>同一订单持续流转</div><div>工单关联已交付订单</div></div></div>'''
slides=[]
def slide(title,body,speech):slides.append((title,body,speech))
slide('匠造智服', '<p class="eyebrow">工程装备服务协同</p><h1>价值全景与场景实证</h1><p class="lead">围绕一台设备的租购与服务，把客户需求、交付进度和维修责任组织成可执行、可追溯的业务过程。</p><p><span class="accent">作品名称：三一匠造 3.5.0</span></p><p>建议展示时长：10 分钟，另留 3—5 分钟答辩。内容路线：业务问题 → 方案全景 → 双端演示 → 技术证据 → 演进边界。</p>'+note('“匠造智服”作为本次展示主题，不更改软件原名；“智服”指流程化服务协同，不代表已实现 AI 决策。'), '各位老师好，我展示的是三一匠造工程装备租购与售后服务平台。项目聚焦一个具体问题：客户提出设备需求之后，怎样让工作人员持续跟进，并让交付和维修都有记录、有责任人、有确认结果。下面我将用一条订单和一条售后工单说明。')
slide('01 从业务断点出发',cards([('需求信息分散','客户描述、设备清单和工程资料容易散落在聊天或文档中，受理人员难以快速还原上下文。'),('交付进度不透明','客户需要反复询问订单进度，工作人员也需要确认报价、备货和发运分别到了哪一步。'),('维修交接缺少依据','只有“处理好了”的口头反馈，不足以说明谁处理、依据是什么、客户是否认可。'),('跟进动作容易遗漏','记录“当前是什么状态”之外，还需要明确“谁在什么时候做下一件事”。')])+note('以上为本作品设定的典型业务场景，尚无企业现场调研样本或量化损失测算。'), '我的设计起点不是把功能堆在一起，而是围绕服务中的四个断点：需求、进度、证据和跟进。对应地，我把这些信息放进业务单据，并通过状态、材料、角色和待办组织起来。这些痛点是项目的场景假设，实际企业收益还需要试点验证。')
slide('02 价值主张与设计原则',cards([('业务连续性','客户可查询同一订单的后续交付与维保信息，工作人员围绕记录开展处理，减少上下文丢失。'),('责任可追溯','状态变更留存操作者、时间、说明和材料；维修处理人与材料审核人分离。'),('行动可管理','跟进计划关联具体业务，标明负责人和截止时间，支持延期说明和实际结果记录。'),('部署可演示','同一电脑作为服务端，两个独立浏览器扮演客户与管理角色；网页与桌面壳复用业务服务。')])+note('价值验证建议：试点记录需求受理耗时、交付查询次数、维修退回原因、逾期待办数量；当前不宣称提升百分比或真实营收增长。'), '这个项目的价值可以概括为：事情接得住、过程看得见、责任查得到。技术设计上，页面负责交互，服务端负责权限和流程校验，数据库保存业务记录。展示成功的标准不是页面好看，而是客户提交后另一端能看见，审核之后客户能继续完成验收。')
slide('03 项目能力导图',flow(['三一匠造<small>工程装备服务协同</small>'])+cards([('客户服务入口','设备选购 → 项目需求 → 租购申请 → 进度查询 → 客服沟通 → 收货与报修 → 服务验收'),('工作人员工作台','需求审核 → 订单处理 → 派单维修 → 独立审核 → 全流程跟进 → 今日概览'),('管理支撑','产品与参考价维护、员工与权限、材料与历史、操作审计。'),('技术底座','Web 界面 + Node.js 本机 HTTP 服务 + SQLite；Electron 提供 Windows 桌面入口。')])+note('客户端与管理员端是同一服务的两类入口；工程师和审核员属于工作端的不同角色。'), '这张图把所有功能收敛为客户入口、工作人员工作台和管理支撑。设备目录和 3D 负责帮助理解产品，真正的主线是订单交付和售后服务。功能看似分布在多个菜单，实际上围绕同一类工程装备服务场景展开。')
slide('04 双端业务全景',lanes+note('当前存在一处关键断点：工程需求完成后，需要客户另行提交租购申请；系统尚未实现项目转订单及自动关系回填。',True), '请沿着两条泳道来看：上面是客户，下面是工作人员。客户提出需求，工作人员受理沟通；进入订单后，双方通过同一订单协作。收货后报修与原订单关联。这里我也说明一个当前边界：项目需求不能一键转订单，需要另行下单，所以我不会把它说成完整的线索到回款系统。')
slide('05 售前 售中 售后如何划分',table(['业务层次','功能范围','形成的业务依据','边界'],matrix), '如果老师问项目究竟属于售前还是售后，我会回答：主线是工程装备租购交付与售后协同，同时覆盖售前需求受理。工程需求属于售前，报价确认到收货属于售中，维修与验收属于售后。跟进管理横跨三个阶段，记录下一步行动，但不能代替业务审核或客户确认。')
slide('06 对 L2C 的支撑与边界', '<p>L2C 与 LTC 都指 Lead to Cash（线索到回款）；华为公开材料常用 LTC，将其核心业务归纳为 ML、MO、MCE 三部分。</p>'+table(['参考环节','本项目判断','已具备的支撑','尚缺少的能力'],ltc)+f'<p class="muted">框架依据：<a href="{SOURCE}">华为云 2022-11-29 活动回顾，LTC 流程分享</a>。上表为本项目功能映射判断，不是华为官方认证或完整框架复刻。</p>', '我借鉴的是从客户需求出发、贯穿业务过程的思想。目前对线索和机会环节提供的是部分支撑，对订单交付和售后服务有明确的操作链路。合同、开票和回款还没有实现，因此定位是 L2C 相关环节的业务协同实践，而不是完整 L2C 平台。')
slide('07 现场双端协同演示', '<p class="lead">用一条业务记录，让评委看到“提交、同步、处理、确认”。</p>'+flow(['A 客户<small>提交申请／发消息</small>','B 管理员<small>刷新并受理订单</small>','A 客户<small>重新查询进度／收货</small>','B → A<small>售后审核／客户验收</small>'])+cards([('7 分钟主线','目录与需求 1 分钟；下单和双向聊天 2 分钟；报价至交付 2 分钟；既有维修单审核与客户验收 2 分钟。'),('角色切换原则','客户使用 Edge，管理员使用 Chrome。完整维修处理需要服务工程师账号；仅两浏览器时，在 B 端先退出再切换工程师，之后换回管理员审核。')])+'<div class="toolbar"><a class="button" href="双端协同演示.html">进入交互式排练</a><a class="button" href="系统操作手册.html">打开逐步操作手册</a></div>'+note('聊天约 1.5 秒轮询；订单、工单与统计使用刷新或重新查询。交互排练页不会自动操作实际系统。'), '下面进入实际演示。A 浏览器是客户，B 浏览器是管理员。先看同一个订单编号能否在两端对应，再看消息能否同步，然后推进交付。售后部分为控制时间，可以从已经准备的待审核工单开始，但必须明确说明前面的维修步骤已提前准备，而不是现场完成。')
slide('08 演示样本与指标口径','<div class="grid"><div class="panel"><span class="big">15</span>演示订单</div><div class="panel"><span class="big">4</span>关联售后工单</div></div>'+table(['卡片','2026-10-26 造数完成时','含义'],[['待受理订单','5','order.status = submitted'],['在途维保工单','4','ticket.status ≠ closed，含待派单、处理中、待审核等未关闭状态'],['待材料审核','2','ticket.status = pending_review，是在途工单的子集'],['累计订单','15','全部订单记录数，不等于已成交或已回款数']])+note('这些数字是演示造数完成时的快照，不是企业经营成绩；后续演示操作会使数字变化。“今日工作概览”中的四张卡并未按当天筛选。'), '为了让老师能直接看到不同状态，我准备了十五条明确标注的演示订单和四条维修工单。这里需要区分两个口径：累计订单包括申请，不能当成销售业绩；待审核工单包含在未关闭工单中，不能把两者相加。当前卡片是全量统计，不是当天新增量。')
slide('09 架构与关键控制', '<div class="architecture"><div class="panel">Edge 客户端<br>客户查询与提交</div><div class="panel">Chrome 管理工作端<br>按岗位处理业务</div><div class="panel wide">HTTP 本机服务 · Node.js<br>会话鉴权 ／ 状态校验 ／ revision 冲突检测 ／ 事务与审计</div><div class="panel wide">SQLite 持久化<br>records 业务记录 · files 附件 · audit 操作日志</div></div>'+note('网页版采用 B/S 组织方式；Electron 是桌面封装入口。SQLite 由应用运行时使用，无需另装数据库服务，也不是 Windows 自带业务数据库。业务持久化与浏览器临时状态是不同层次。'), '两端不是各存一份数据，而是请求同一个服务。服务核对角色、当前状态和记录版本，再把业务数据保存到 SQLite。这样刷新页面后业务记录仍在。桌面程序与网页不是两套业务系统，桌面程序主要提供打包运行和窗口体验。')
slide('10 可验证成果与应用边界',table(['证据','可说明什么','不能由此推导什么'],[['现有回归日志：148 项测试通过','已有自动化测试覆盖范围通过','不等于所有功能无缺陷或具备生产容量'],['现有 Edge／Chrome 双浏览器回放：8 步通过','下单、双向消息、刷新保留、报价／备货／发运／收货可协同','该回放未覆盖售后现场验收或跨电脑联网'],['演示造数记录：15 单、4 工单','业务记录与四张指标卡对应，包含待审核样本','不代表真实客户数量、销量或收入'],['代码实现：独立审核与客户验收','维修处理、审核、客户确认分别受约束','现场完整售后流程仍应按操作手册排练']])+note('正式应用前优先补齐客户身份验证、注册授权、网络部署与备份机制；当前未完成跨电脑或公网场景验收。',True), '目前已有自动化测试和双浏览器实证记录，能支撑我展示的具体结论。但我会把自动化通过、实际浏览器演示和未来生产能力分开讲。尤其是客户按电话查询、演示角色自由注册，都是比赛场景便利设计，正式部署必须调整。')
slide('11 迭代路径与价值收束',flow(['第一阶段<small>需求转订单、主数据关联</small>','第二阶段<small>报价版本、合同与库存衔接</small>','第三阶段<small>开票应收、回款核销</small>','第四阶段<small>身份、部署、备份与运营验收</small>'])+note('上图是功能演进顺序；安全与部署治理应在任何正式上线之前完成，而不是等所有业务功能结束。所有未实现能力均属于规划。')+'<p class="lead">本作品的核心成果，是把工程装备服务过程变成“有入口、有状态、有材料、有责任、有客户确认”的协同流程。</p><p>评价重点：场景理解、流程实现、角色边界、数据一致性、展示可复现性，以及对现阶段不足的清晰认识。</p>', '我的阶段性成果是把客户需求、订单交付和售后处理组织成可以操作的流程，并用两个浏览器展示协同。下一步最值得优先做的是项目转订单，减少售前与售中的断点，再逐步补齐合同与回款。项目的价值不是宣称做完所有企业管理，而是把选定场景做清楚、跑通并留有扩展路径。')
body='<div class="toolbar noprint"><button id="present" class="primary">进入展示模式</button><button id="notes">展开／收起讲解提示</button><button onclick="window.print()">打印／保存 PDF</button><span>方向键翻页；Esc 返回全览</span></div><div class="toolbar slides-only"><button id="prev">上一页</button><span id="count"></span><button id="next">下一页</button></div>'
for i,(title,content,speech) in enumerate(slides):body+=f'<section class="slide" id="s{i}"><p class="eyebrow">{i+1:02d} / {len(slides):02d}</p><h2>{title}</h2>{content}<details class="speaker"><summary>参赛选手讲解提示</summary><p>{speech}</p></details></section>'
body+=section('附件与阅读路径','<p>首次准备：先读术语解读 → 阅读主展示文件 → 跟随双端演示页排练 → 对照答辩指引回答问题。</p>'+''.join('<p><a href="'+f+'">'+n+'</a></p>' for f,n in nav[1:])+'<p><a href="演示数据索引.html">演示数据索引与选单建议</a> · <a href="证据与资料索引.html">证据与资料索引</a></p>')
page('index.html','匠造智服 工程装备服务协同价值全景与场景实证',body,"""let pos=0;const slides=[...document.querySelectorAll('.slide')];function show(){slides.forEach((s,i)=>s.classList.toggle('current',i===pos));document.querySelector('#count').textContent=(pos+1)+' / '+slides.length;document.querySelector('#prev').disabled=pos===0;document.querySelector('#next').disabled=pos===slides.length-1;}document.querySelector('#present').onclick=()=>{document.body.classList.toggle('slide-mode');show();window.scrollTo(0,0)};document.querySelector('#notes').onclick=()=>{document.body.classList.toggle('notes');document.querySelectorAll('.speaker').forEach(d=>d.open=document.body.classList.contains('notes'));};document.querySelector('#prev').onclick=()=>{pos=Math.max(0,pos-1);show()};document.querySelector('#next').onclick=()=>{pos=Math.min(slides.length-1,pos+1);show()};document.addEventListener('keydown',e=>{if(!document.body.classList.contains('slide-mode'))return;if(e.key==='ArrowRight'){e.preventDefault();document.querySelector('#next').click()}if(e.key==='ArrowLeft'){e.preventDefault();document.querySelector('#prev').click()}if(e.key==='Escape')document.body.classList.remove('slide-mode')});show();""")

steps=[
('演示准备','在 Edge 打开客户平台，保持客户身份。','在 Chrome 登录管理员；完整维修分支另准备一位服务工程师。','两个浏览器访问同一台电脑正在运行的服务。','账号登录是角色边界，不是浏览器名称决定权限。'),
('售前需求','在“项目需求”填写演示项目；普通模式附设备清单或材料，保密模式仅提清单。','在“项目需求工单”查看同一项目，开始审核并反馈；可建立关联跟进。','需求被受理并有审核记录。保存项目查询凭证，不公开展示凭证。','项目不会自动转订单，下一步另行提交租购申请。'),
('提交订单','“设备选购”选可下单的官网设备，填写购买／租赁申请和测试联系方式。','进入“售中与交付订单”，点击“刷新数据”，按同一订单编号查找。','两端订单编号、设备与联系人一致，订单为待受理。','教学 3D 模型不作为在售商品。只填演示资料。'),
('双向沟通','从本单进入客服，发送“请确认演示设备交付计划”。','打开相应本机客服会话，回复“已收到，正在核对方案”。','双方均看到消息；等待一轮约 1.5 秒轮询，网络负载可能影响时间。','这是本机服务内聊天，不是微信、短信或公网即时通信。'),
('确认报价','重新查询订单，核对“已确认报价”和模拟报价。','订单详情填写报价、说明并上传演示材料，提交确认。','订单由待受理变为已确认报价。','报价只是工作人员录入；没有付款行为，也没有正式合同。'),
('备货与发运','重新查询订单，查看备货和发运状态。','先登记备货，再登记发运；每步补充材料和说明，发运填写模拟承运方、单号。','订单按顺序变为备货中、待收货。','不能跳步；当前没有库存扣减和真实物流查询接口。'),
('客户确认收货','在待收货订单上传演示确认材料，确认收货。','刷新本单，查看“已交付”及客户确认记录。','同一订单两端均为已交付。','工作人员不能冒充客户通过员工入口完成收货。'),
('售后报修与派单','在已交付订单点击“提交维保报修”，填写虚构故障与材料。','进入“售后维保工单”，选择在用服务工程师并保存派单说明、材料。','新工单关联原订单，状态待工程师接单。','工单与订单关联；只有已交付订单才能提交维保。'),
('工程师处理','查看工单进度，等待处理结果。','B 端退出管理员，登录被指派的服务工程师；开始维修处理，再提交材料审核。','维修处理中 → 待材料审核，历史可查。','不是任意员工都能提交维修进度，必须是被指派工程师。'),
('独立审核','等待审核后重新查询工单。','B 端退出工程师，切回另一位管理员或审核员；核对材料并提交通过意见。','工单进入待客户验收。','审核人不能是本工单的维修处理人；审核通过不等于工单关闭。'),
('客户验收闭环','上传演示验收材料，选择验收通过；若仍有问题，选择退回。','刷新工单查看已完成及完整历史。','通过则关闭；退回则重新进入维修处理中。','客户是服务结果确认者。退回场景建议另选样本，避免打断主线。'),
('跟进与回看','核对订单与工单最终结果。','在“全流程跟进”关联原单建立回访任务，指定负责人和未来截止时间；完成时填写结果。','任务按待跟进／已完成独立管理；业务单据不会因此跳转。','展示四张卡的变化，并说明它们是全量记录数，不是营业收入。')]
stepjson=json.dumps(steps,ensure_ascii=False)
body='<p class="eyebrow">SCENARIO ORCHESTRATION</p><h1>双端协同场景实证</h1><p>此页为交互式排练指引：切换步骤可查看两端动作、预期结果和讲解重点。实际业务操作请在 Edge 与 Chrome 中手动完成。</p><div class="toolbar"><a class="button" href="http://127.0.0.1:8790/?workspace=customer#catalog" target="_blank" rel="noopener">打开实际客户端</a><a class="button" href="http://127.0.0.1:8790/?workspace=staff#work" target="_blank" rel="noopener">打开实际管理工作端</a></div>'+note('链接会使用当前默认浏览器，不会自动指定 Edge／Chrome。要演示独立浏览器，请分别复制对应地址打开。此排练页无业务写入，也不保存账号或凭证。')+'<div class="stepnav" id="stepnav"></div><div class="progress"><i id="bar"></i></div><h2 id="stepTitle" aria-live="polite"></h2><div class="grid"><div class="panel"><span class="tag">A / 客户端</span><p id="client"></p></div><div class="panel"><span class="tag">B / 管理工作端</span><p id="staff"></p></div></div><div class="note"><b>核验结果</b><p id="expected"></p></div><div class="note boundary"><b>讲解边界</b><p id="limit"></p></div><div class="toolbar"><button id="back">上一步</button><button id="forward" class="primary">下一步</button><button id="reset">回到起点</button><span id="stepCount"></span></div>'+section('7 分钟精简路线','<p>步骤 1—7 展示一条新订单；售后可使用现有“参赛演示客户14／15”的待审核样本，跳到步骤 10—11。请说明售后样本与刚下的订单不同，前置处理已准备；不要把拼接样本说成同一笔业务的全程实录。</p><p>若时间充足，按 12 步完成同一订单链路，建议另留 5 分钟用于角色切换与材料上传。</p>')+'<details id="design"><summary>双端协同演示功能设计说明</summary><h3>价值与设计导入</h3><p>帮助参赛者在客户与管理工作端之间准确切换，避免漏讲角色和验收条件；角色包括参赛者、旁观评委，实际业务角色另由软件账号决定。</p><h3>逻辑与字段规则</h3><p>每一步包含标题、客户端动作、工作端动作、预期结果和边界五项固定文本。步骤为 1—12；上一／下一步不可越界，回到起点重置当前序号，不清除实际业务数据。</p><h3>取数与口径</h3><p>内容来自当前 3.5.0 功能及操作流程的人工整理，不实时读取数据库。进度条仅表示指引页序号占全部步骤比例，不能作为业务完成率。</p><h3>权限、异常与接口边界</h3><p>不请求业务 API、不保管登录信息。打开实际系统是新标签导航；若本机服务未启动，按操作手册启动后重试。当前步骤只存在页面内存，刷新回到第一步。排练不代表现场实测完成。</p><footer>原型来源方：SDMC-IT</footer></details>'+section('完整步骤打印版',table(['步骤','客户端','管理工作端','核验与边界'],[[str(i+1)+' '+s[0],s[1],s[2],s[3]+' '+s[4]] for i,s in enumerate(steps)]))
page('双端协同演示.html','双端协同场景实证',body,"const steps="+stepjson+";let at=0;const nav=document.querySelector('#stepnav');steps.forEach((s,i)=>{const b=document.createElement('button');b.textContent=(i+1)+' '+s[0];b.onclick=()=>{at=i;render()};nav.appendChild(b)});function render(){const s=steps[at];['stepTitle','client','staff','expected','limit'].forEach((id,i)=>document.getElementById(id).textContent=s[i]);document.querySelector('#bar').style.width=((at+1)/steps.length*100)+'%';document.querySelector('#stepCount').textContent=(at+1)+' / '+steps.length;document.querySelector('#back').disabled=at===0;document.querySelector('#forward').disabled=at===steps.length-1;[...nav.children].forEach((b,i)=>{b.classList.toggle('current',i===at);b.setAttribute('aria-pressed',i===at)})}document.querySelector('#back').onclick=()=>{at--;render()};document.querySelector('#forward').onclick=()=>{at++;render()};document.querySelector('#reset').onclick=()=>{at=0;render()};render();")

body='<p class="eyebrow">SOLUTION DESIGN</p><h1>系统设计说明</h1><p class="lead">以业务记录为载体，以角色权限和状态迁移约束服务过程。</p>'
body+=section('1 定位与设计目标','<p>系统面向工程装备客户、服务人员、审核人员和管理员，覆盖需求受理、租购交付、售后闭环及跨环节跟进。设计目标是将需求、动作、材料和确认结果留在同一业务环境中。当前为本机教学与参赛实现，不承担正式交易、支付或生产运营。</p>'+table(['角色','允许的核心动作','限制'],[['客户','提交需求与订单、查询本单、沟通、收货、报修、验收','不能访问内部跟进或管理员接口'],['服务工程师','处理订单、项目需求、客服；处理被指派维修单；管理自己的跟进','不能审核维修材料；不能替其他工程师提交维修进度'],['审核员','独立审核维修材料、查看相关记录；只读跟进','不能审核自己处理的工单；不能写跟进'],['管理员','产品和账号管理、订单处理、派单、独立审核、分配和改派跟进','仍受流程及禁止自审约束；不是客户确认的替代者']]))
body+=section('2 分层架构与存储','<p>表现层由 dist/ 下 HTML、CSS、JavaScript 组成；业务层由 server/platform.cjs 提供 HTTP 路由、身份检查与事务，project-service.cjs 承载项目与客服，followup-service.cjs 承载跟进。desktop/main.cjs 用 Electron 包装窗口与本机服务。</p>'+flow(['浏览器／Electron','HTTP 业务服务','SQLite 数据库'])+table(['存储对象','内容与生成逻辑','使用边界'],[['records(kind,id,body)','按 kind 区分 user、product、project、order、ticket、conversation、followup；body 保存 JSON 业务记录','这是通用记录表，不应画成已经存在的七张独立业务表'],['files','附件元数据与 bytes BLOB，由上传校验通过后落库','附件是数据库内容，不只是浏览器缓存'],['audit','操作者、动作、对象、时间等操作轨迹','用于追溯，不等于不可篡改的合规存证'],['浏览器本地存储及会话','界面偏好、主动保存的快捷入口与会话相关状态','不承担全部业务主存储；不同浏览器不共享登录'],['服务内存','登录会话与挑战等临时对象','服务重启可能需要重新登录；业务记录仍保存在 SQLite']])+'<p>默认业务库位于 <code>%APPDATA%\sany-forge-platform\platform.sqlite</code>。运行时使用 SQLite，便携版随程序具备所需运行环境；网页版独立启动需要 Node.js 24。数据保存到本机磁盘，不会自动同步到其他电脑。</p>')
body+=section('3 核心对象关系',flow(['项目需求 PR<small>独立受理</small>','人工另行提交<small>尚无自动转单关系</small>','租购订单 SO','售后工单 WO<small>orderId 关联</small>'])+'<p>会话关联项目或订单；跟进记录通过 kind 与 recordId 关联项目、订单或工单，通过 ownerId 关联员工。订单保留设备摘要，历史订单不会因商品下架而消失。附件通过 owner_kind、owner_id 关联业务记录。</p>')
body+=section('4 状态机与异常分支',table(['对象','主流程','退回／例外'],[['工程需求','submitted → reviewing → accepted → closed','submitted 或 reviewing 可转 needs_info；客户补充后重新提交'],['订单','submitted → confirmed → preparing → shipped → delivered','submitted／confirmed 可取消；发运与收货不能跳步'],['维保工单','submitted → assigned → in_progress → pending_review → awaiting_customer → closed','材料审核拒绝或客户验收退回，都回到 in_progress'],['跟进任务','open → done','open 可调整负责人及截止时间；done 不可再次完成；逾期为计算属性']])+'<p>订单与维修的状态变更须提供说明和材料；报价金额为有效正数，最多两位小数。发运须填承运方和单号。revision 用于检测旧页面提交冲突：冲突后刷新记录、核对最新状态，再重新操作。事务保证一次业务操作的记录与附件等写入共同提交或回滚。</p>')
body+=section('5 字段与材料规则',table(['功能','关键字段及规则','生成／取数说明'],[['需求受理','项目名、联系人、电话；普通模式至少清单或材料之一；保密模式必须有设备清单且不接受附件','清单选自有效产品；最多50行，每行1—999台；项目完成不自动成交'],['租购申请','产品、购买／租赁、数量1—999、联系人、电话、详细地址、计划日期；租赁周期1—120','产品来自发布目录；教学条目不可下单；日期不能早于当天'],['订单处理','报价、说明、材料；发运填写承运方、单号','报价来自工作人员录入，非支付结果；发运信息为人工登记'],['售后服务','已交付订单、故障、联系信息、紧急程度；指派在用 service 用户','维修历史记录责任人；独立审核后等待客户验收'],['跟进计划','关联单据、负责人、行动≤1000字、未来截止时间、普通／紧急；结果或调整原因≤2000字','服务端校验；时间统一保存、显示按本机环境转换'],['附件','JPG、PNG、WebP、PDF、DOCX；每次最多4份，每份≤4MB','验证格式与大小；DOCX另验结构，不等于病毒扫描；保密项目路径拒绝资料附件']]))
body+=section('6 指标三层口径',table(['指标','数据源头','生成与清洗逻辑','查询／汇总口径'],[['待受理订单','records.kind=order','合法申请生成 submitted；状态变更由服务校验','status=submitted 条数，全量，无当天限制'],['在途维保工单','records.kind=ticket','已交付订单生成工单；审核、验收推进状态','status≠closed 条数，待审核包含在内'],['待材料审核','records.kind=ticket','被指派工程师提交完工材料后进入 pending_review','status=pending_review 条数'],['累计订单','records.kind=order','包括购买和租赁申请，保留取消等状态','全部订单条数，不等于成交额或销量'],['逾期跟进','records.kind=followup','按服务端本次 asOf 比较 dueAt；不从聊天自动生成任务','status=open 且 dueAt<asOf；按任务数计，不按订单去重'],['目录数量','发布产品集合','官网商品与教学展示条目分别保留；不自动补缺失规格','商品量与教学模型量分列，不把570全部叫在售设备']]))
body+=section('7 关键接口与代码定位',table(['用途','接口族','实现位置'],[['目录与订单','GET /api/products；POST /api/orders；/api/orders/:id/transition、confirm','server/platform.cjs'],['维保闭环','/api/tickets；/api/tickets/:id/transition、review、accept','server/platform.cjs'],['需求与会话','/api/projects、/api/conversations 相关路由','server/project-service.cjs'],['跟进','GET/POST /api/followups；/:id/complete、reschedule','server/followup-service.cjs'],['统计、员工和目录管理','/api/stats、/api/staff、/api/admin/users、/api/admin/products','server/platform.cjs']])+'<p>路径用于设计追溯，不是可绕过身份校验的公开调用说明。客户会话绑定具体记录，员工操作根据角色检查；当前员工范围较宽，组织或区域级数据隔离尚未建设。</p>')
body+=section('8 当前风险与迭代验收','<ol><li>需求转订单：新增明确关联与客户确认；验证重复提交不会多生订单，原项目能回查订单。</li><li>交易能力：报价版本、合同与变更先行，之后再建设发票、应收与回款；交付签收不能代替回款。</li><li>正式部署：关闭自由选角色注册，补客户身份验证、网络安全和备份恢复演练；不得直接把本机端口暴露公网。</li><li>服务运营：资产、质保与备件台账稳定后，再定义 SLA；目前逾期任务不等于 SLA 违约。</li></ol><p>已有设计入口：实际系统菜单“全流程跟进功能设计说明”。其他功能本文件提供设计资料，不宣称原系统已为每项功能提供独立内置设计页。</p>')
page('系统设计说明.html','匠造智服 系统设计说明',body)

body='<p class="eyebrow">OPERATIONS PLAYBOOK</p><h1>系统操作手册</h1><p>面向参赛排练和本机操作，按客户、管理员、工程师与审核角色区分步骤。</p>'
body+=section('1 启动与准备','<ol><li>推荐打开作品根目录的“三一匠造-3.5.0-服务平台-Windows便携版.exe”；如当前网页版已运行，可直接使用现有服务，不重复启动其他版本。</li><li>源码方式：进入 sany-forge-ui-optimized，运行“启动网页版.cmd”，需要已有 Node.js 24。使用期间保持服务运行。</li><li>Edge 打开客户端 <code>http://127.0.0.1:8790/?workspace=customer#catalog</code>；Chrome 打开工作端 <code>http://127.0.0.1:8790/?workspace=staff#work</code>。</li><li>使用本人准备的演示管理员账号。完整售后另备 service 工程师账号；不在展示材料中写入密码或访问凭证。管理员可在员工与权限中创建／管理账号。</li><li>准备“演示材料.png”，所有金额、物流和故障均注明虚构。规划10分钟展示和3—5分钟答辩。</li></ol>'+note('预置“参赛演示工程师”仅用于造数，其登录口令不在资料中提供。若要从头演示维修，请新建可登录的工程师账号并指派给该账号；主线不依赖恢复造数账号密码。'))
body+=section('2 客户端操作','<ol><li>设备选购：按分类或搜索找设备，查看规格；缺失信息以页面说明为准，不自行补报设备价格。</li><li>项目需求：填写工程描述和联系人；普通模式至少选择设备或提供材料。保密模式只提交设备清单，不上传设计资料。保存项目查询信息。</li><li>租购申请：选购买／租赁，填写数量、联系信息、详细地址及计划日期。提交后记录可读订单号和测试联系电话。</li><li>订单与售后：输入完整下单电话，选择订单；该电话入口仅作本机演示，未接短信认证。</li><li>联系客服：进入该单会话，发送文字；确认对端收到。刷新页面后可以重新查询业务。</li><li>收货：订单为待收货时，补充说明、材料并确认收货。</li><li>报修：已交付订单点击“提交维保报修”，填写故障和联系信息。等待处理与审核后，上传验收材料并提交通过或退回。</li></ol>')
body+=section('3 管理员与工程师操作','<ol><li>今日工作概览：点击“刷新数据”，查看待受理、未关闭维保、待材料审核和累计订单。注意不是当天统计。</li><li>项目需求工单：查看资料或保密设备清单，开始审核；需要补充则退回，由客户补充后再审核。受理与完成不代表实际成交。</li><li>售中与交付订单：按编号查找申请，录入模拟报价、说明和材料，确认报价；逐步备货，再填写物流并发运。</li><li>售后维保工单：管理员选在用服务工程师，上传派单材料并保存。工程师登录自己的账号，接单、登记维修处理，再上传完工材料提交审核。</li><li>独立审核：由未参与维修的管理员或审核员核对材料，选择通过或退回；通过后等待客户验收。</li><li>全流程跟进：点“新增跟进计划”，选关联单据，填负责人、下次行动、未来截止时间及优先级。结果填写后完成；改期需说明原因。</li><li>管理后台：维护目录、参考价依据、员工账号；产品下架不删除历史订单。参赛现场避免临时改动无关目录或权限。</li></ol>'+note('只有被指派工程师能推进维修；管理员负责管理与审核并不意味着能代替工程师处理。两个浏览器可以完成多角色演示，但 B 浏览器需先退出再切换账号。'))
body+=section('4 演示检查清单',table(['时点','检查项','通过条件'],[['上台前','服务、两个浏览器、账号、材料、订单索引','首页可开；B已登录；演示材料可选；选单编号明确'],['提交后','双端同一订单','编号、设备、联系人一致'],['沟通后','双向消息','双方看到各自发送与接收的文本'],['交付后','客户签收','A确认，B刷新为已交付'],['售后后','独立审核与客户验收','工程师提交、另一人审核、客户确认，历史完整'],['结束前','数据口径与边界','说明演示数据；不把订单数量当销量、报价当回款']]))
body+=section('5 常见异常与恢复',table(['现象','处理方式'],[['页面打不开','确认本机服务仍运行；检查是否已有服务占用8790，不随意结束不认识的进程；不要直接用文件方式打开 dist/index.html。'],['另一端没看到订单','核对双方地址、订单编号和联系方式；在工作台刷新，客户重新查询。不同电脑的127.0.0.1不是同一服务。'],['消息暂未出现','打开正确订单会话，等待轮询；检查页面与服务连接。聊天同步与订单刷新机制不同。'],['按钮不见或提示无权限','核对登录角色、工单指派人和当前状态；不通过换浏览器冒充授权。'],['提示版本冲突','刷新详情，核对别人刚做的处理；重新填写当前允许的动作。'],['材料被拒绝','检查格式、单份4MB、单次4份限制；保密工程不允许附件；使用附带的演示PNG。'],['员工会话失效','重新登录；重启服务会丢失内存会话，不意味着订单丢失。'],['现场来不及完整维修','明确切换到事先准备的待审核样本，按索引演示；不要声称跳过步骤的同一单完整闭环。']]))
body+=section('6 数据保留与演示纪律','<p>演示数据存于本机 SQLite，刷新不会清空。不要通过删除数据库来重置现场，也不要反复执行造数脚本。维护时先正常停止所有使用该库的程序，再按受控流程备份完整业务资料目录，备份须妥善保管；本资料包不包含数据库、账号密码、人脸密钥或订单访问凭证。跨电脑迁移和备份恢复应另行验证。</p><p>现有样本会随操作改变，不保证始终为5／4／2／15；需要固定画面时使用演示数据索引的基线说明，而不是篡改统计数字。</p>')
page('系统操作手册.html','匠造智服 系统操作手册',body)

questions=[('项目为什么看起来功能很多，主线是什么？','主线是工程装备租购交付与售后服务协同。目录帮助选型，项目需求承接售前，订单负责交付，维保负责服务，跟进记录下一步行动。它们服务于同一场景。'),('到底属于售前、售中还是售后？','三个阶段都有覆盖，但深度不同：售前是需求入口和沟通，售中是订单交付，售后是维修审核与验收。核心展示重点放在后两条业务链。'),('你实现了华为的 L2C 吗？','我借鉴了端到端流程思想，支撑需求、报价沟通和交付等部分环节，没有实现完整商机、合同、开票和回款，所以不能称完整 L2C。'),('平台的创新点在哪里？','作品层面的特点是把状态约束、材料留痕、独立审核、客户确认与跟进待办组合进工程装备场景，并用双端演示验证协作。这是应用设计和实现的整合，尚不能宣称行业首创。'),('为什么两个浏览器可以看到同一条记录？','因为两个浏览器请求同一本机服务，服务把业务记录存到同一个 SQLite 数据库；浏览器只分离身份和操作入口。'),('这是什么架构？数据库要安装吗？','网页版是 B/S，桌面入口使用 Electron 封装。SQLite 是嵌入式数据库，便携程序已有运行环境，无需单独安装数据库服务；它不是Windows自带业务数据库。'),('是不是已经能给手机和另一台电脑用了？','当前服务只供本机访问，其他设备的127.0.0.1指向它们自己。手机跨设备访问、网络部署和身份安全尚未完成验证。'),('收入和效率提升了多少？','当前没有企业试点样本，因此不报告收益百分比。可通过受理耗时、重复询问次数和维修退回率等指标，在试点中比较改进前后的效果。'),('为什么不能让工程师自己审核？','维修过程与材料确认分离可以减少责任混同。系统限制自己处理的工单不能由自己审核，审核通过后还需要客户验收。'),('这十五条订单是真实业务吗？','是为参赛创建的合成数据，均有明确标注。它们经过业务接口和状态流程保存，用于展示不同状态，不代表真实销售或收入。'),('三一品牌、产品和3D是什么关系？','产品资料参考官方公开目录，作品不是三一官方销售系统，也不表示获得官方授权。3D是教学模型，不保证与所有真实设备一一对应，不是数字孪生。'),('AI做了什么？开发是你独立完成的吗？','软件当前不能宣称具备AI自动诊断或自动决策。开发过程中有AI辅助分析、改进和测试；我会如实说明自己的需求梳理、业务理解、代码掌握与演示贡献，并以实际参与记录为准。'),('如果要继续做，第一步是什么？','先补项目需求转订单的显式关联，消除售前到售中的信息断点；正式上线前先完成身份与部署治理，随后扩展合同、开票和回款。')]
body='<p class="eyebrow">REVIEW & DEFENSE</p><h1>评审答辩指引</h1><p>以下是按常见软件作品评审关注点整理的准备建议，不代表本次赛事官方评分标准或获奖预测。</p>'+section('1 评委关注点与展示证据',table(['关注点','应展示的证据','表达建议'],[['问题与价值','需求、交付、维修之间的具体断点','先讲解决谁的问题，再讲用了什么技术'],['功能完成度','同编号双端订单、状态流转、材料和客户确认','用一次操作说明能力，不逐个念菜单'],['技术理解','分层架构、持久化、鉴权、状态机和版本冲突','讲清一个数据从哪里来、怎么变、怎样查'],['设计合理性','独立审核、保密清单、客户确认及跟进边界','解释为什么需要限制，不只展示成功弹窗'],['真实性与规范性','标注演示数据、开源／公开素材来源、AI辅助边界','不冒充官方系统，不虚构行业首创或经营效果'],['可复现性','双浏览器步骤、样本索引、失败恢复方法','现场与预置样本区分，准备清晰的回退路径']]))
body+=section('2 十分钟节奏','<p><b>0:00—1:00</b> 项目定位和问题；<b>1:00—2:00</b> 全景与 L2C 边界；<b>2:00—9:00</b> 双端交互演示；<b>9:00—10:00</b> 技术控制、验证证据和下一步。若时间不足，优先展示同单协同与客户确认，减少装饰动画和目录浏览。</p>')
body+=section('3 高频追问与建议回答',''.join('<details open><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in questions))
body+=section('4 建议避免的说法',table(['不宜直接宣称','建议表述'],[['完整打通L2C','支撑L2C部分环节，交付与售后形成可操作链路'],['实时库存与物流','登记备货与发运状态，物流字段由工作人员填写'],['数字孪生和AI诊断','教学3D展示；当前没有实时设备映射与自动诊断'],['企业级安全、无限并发','已有角色和流程校验；生产安全与容量待专项验证'],['销量15单、营收若干','15条参赛演示订单，非经营成绩'],['全流程100%覆盖','逐项说明已实现、部分支撑和未实现；无统一分母不计算覆盖率']]))
page('评审答辩指引.html','匠造智服 评审答辩指引',body)

terms=[('L2C／LTC','Lead to Cash，从线索到回款。','从发现谁可能买，到钱真正到账的一整笔生意。本项目只做到了其中一部分。'),('ML／MO／MCE','管理线索／管理机会点／管理合同执行。','先找需求，再判断和争取生意，最后履行承诺并收款。项目主要支撑需求沟通与订单交付片段。'),('端到端','围绕一个业务目标贯穿起点到结果。','不是只填一张表，而是有人接、有人做、有人确认。当前项目需求到订单还不能自动衔接。'),('闭环','起始、处理、确认及可追溯结果形成完整链条。','修好了还要审核和客户认可，工单才真正结束。'),('业务协同','多个角色围绕同一业务记录分工处理。','客户下单，工作人员看同一单；不用各存一份互相猜。'),('状态机','限定记录可处于哪些状态、允许如何迁移。','办事要按步骤，不能没发货就直接签收。'),('RBAC','Role-Based Access Control，按角色授权。','不同岗位拿不同钥匙。角色控制不等于已经具备全部企业权限体系。'),('职责分离／独立审核','执行人与审核人分开。','谁维修，不能再自己给自己审核通过。'),('审计留痕','记录谁在何时对哪条业务做了什么。','出了问题可以回头查过程，但不是保证永远不能被改的司法存证。'),('revision／乐观并发控制','提交时携带记录版本，防止旧数据覆盖新处理。','两个人同时打开一单，后提交的人先确认别人是不是已经改过。'),('幂等','同一次请求重复提交，结果保持一致。','网络卡了重试，不应重复建立跟进。当前跟进创建有此控制，不代表所有接口都自动防重。'),('事务','一组有关联的数据库操作一起成功或一起回滚。','不能附件存了、业务却只改了一半。'),('B/S','Browser/Server，浏览器与服务器分工。','浏览器是窗口，服务器负责处理。服务器可以就是现场这台电脑。'),('Electron','使用Web技术构建桌面程序的运行框架。','给网页业务装上桌面外壳，方便打包和管理窗口。'),('SQLite与持久化','嵌入式数据库；数据写入磁盘保存。','业务数据放进本机的数据库文件，刷新网页不会消失；它不是Windows送的业务库。'),('缓存与会话','缓存辅助加快访问；会话保存当前访问身份。','临时记住页面或登录，不等于保存所有订单；退出或重启后可能需要再登录。'),('轮询与同步','按间隔查询最新数据并更新界面。','聊天隔一小会问服务器有没有新消息；订单状态仍需刷新或重新查询。'),('SLA','Service Level Agreement，服务级别约定。','例如承诺几小时响应；当前只有跟进截止时间，没有正式SLA计算引擎。'),('主数据与业务单据','主数据描述相对稳定对象，单据记录业务事件。','产品、员工像基础名单，订单、工单像每次办事的记录。'),('回款核销','把收到的钱与应收单据匹配并冲减余额。','钱到账后对上是哪笔账。项目当前没有这一功能。'),('数字孪生','与真实对象持续对应的数据模型及关联机制。','不能只有可旋转的3D就叫数字孪生；本作品目前是教学模型。'),('可追溯与可复现','能查历史；按同样条件和步骤重复验证。','查得到之前谁做了什么，也能让老师跟着步骤再试一次。')]
body='<p class="eyebrow">PLAIN LANGUAGE COMPANION</p><h1>术语白话解读</h1><p class="lead">专业词负责准确，白话负责听懂。答辩时先讲业务例子，再补术语即可。</p>'+''.join('<div class="term"><h3>'+a+'</h3><p><b>专业含义：</b>'+b+'</p><p><b>大白话：</b>'+c+'</p></div>' for a,b,c in terms)+section('一分钟定位练习','<p>“这个项目让买设备的人和提供服务的人，在同一个系统里把事情办完：先提需求，再确认订单、交货，坏了还能报修。工作人员的每一步都有记录，维修要别人审核，最后由客户验收。它借鉴从需求到结果的流程思想，但合同和收款还没做。”</p>')
page('术语白话解读.html','匠造智服 术语白话解读',body)

